#include "trajectory_generator.h"
#include <math.h>
static motion_vec2_t lim(motion_vec2_t v,float m){float n=hypotf(v.x,v.y);if(n>m&&n>0){v.x*=m/n;v.y*=m/n;}return v;}void trajectory_generator_init(trajectory_generator_t*g,motion_vec2_t p,uint64_t t){*g=(trajectory_generator_t){.state={.position=p,.timestamp_us=t},.target=p};}void trajectory_generator_set_target(trajectory_generator_t*g,motion_vec2_t t){g->target=t;}motion_state2_t trajectory_generator_step(trajectory_generator_t*g,const human_motion_model_t*m,uint64_t t){if(t<=g->state.timestamp_us)return g->state;float dt=motion_clampf((t-g->state.timestamp_us)*1e-6f,.0001f,.05f);motion_vec2_t e={g->target.x-g->state.position.x,g->target.y-g->state.position.y};motion_limits_t l=human_motion_model_limits(m,e,motion_clampf(hypotf(e.x,e.y),0,1));motion_vec2_t v=lim((motion_vec2_t){e.x*l.response,e.y*l.response},l.velocity_max),a=lim((motion_vec2_t){(v.x-g->state.velocity.x)/dt,(v.y-g->state.velocity.y)/dt},l.acceleration_max),j=lim((motion_vec2_t){(a.x-g->state.acceleration.x)/dt,(a.y-g->state.acceleration.y)/dt},l.jerk_max);g->state.jerk=j;g->state.acceleration.x+=j.x*dt;g->state.acceleration.y+=j.y*dt;g->state.velocity.x+=g->state.acceleration.x*dt;g->state.velocity.y+=g->state.acceleration.y*dt;g->state.position.x+=g->state.velocity.x*dt;g->state.position.y+=g->state.velocity.y*dt;g->state.timestamp_us=t;return g->state;}
